-- Dumping data for table `products` (14 rows)
INSERT INTO `products` (`id`, `name`, `slug`, `description`, `shortDescription`, `price`, `originalPrice`, `discountPercent`, `category`, `brand`, `images`, `stock`, `rating`, `numReviews`, `isFeatured`, `isNewArrival`, `specifications`, `features`, `tags`, `createdAt`, `updatedAt`) VALUES (1, 'Aura SoundPro X Spatial Headphones', 'aura-soundpro-x-spatial-headphones', 'Experience ultra-rich sound with custom 40mm beryllium drivers, active hybrid noise cancellation up to -45dB, and head-tracking spatial audio. Up to 60 hours of continuous wireless playback on a single charge with fast USB-C charge providing 5 hours in 10 minutes.', 'Hybrid ANC wireless studio-grade headphones with spatial audio tracking.', 299, 379, 21, 'Audio & Sound', 'Aura Audio', '["https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1484704849700-f032a568e944?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1546435770-a3e426bf472b?auto=format&fit=crop&w=1000&q=80"]', 24, 4.9, 48, 1, 0, '[{"key":"Driver Size","value":"40mm Custom Beryllium"},{"key":"Battery Life","value":"Up to 60 Hours (ANC Off), 42 Hours (ANC On)"},{"key":"Connectivity","value":"Bluetooth 5.3, LDAC, aptX Adaptive, 3.5mm Aux"},{"key":"Weight","value":"254g"},{"key":"Noise Cancellation","value":"Active Hybrid ANC (-45dB)"}]', '["Advanced 4-microphone beamforming array for crystal-clear voice calls","Transparency Mode with one-touch capacitive pass-through","Premium memory foam earcups covered in breathable vegan leather","Multipoint connection to switch seamlessly between laptop and phone"]', '["headphones","anc","wireless","audio","spatial"]', '2026-11-05 08:05:37.917 +00:00', '2026-11-05 08:05:37.917 +00:00');
INSERT INTO `products` (`id`, `name`, `slug`, `description`, `shortDescription`, `price`, `originalPrice`, `discountPercent`, `category`, `brand`, `images`, `stock`, `rating`, `numReviews`, `isFeatured`, `isNewArrival`, `specifications`, `features`, `tags`, `createdAt`, `updatedAt`) VALUES (2, 'Chronos Ultra Titanium Smartwatch', 'chronos-ultra-titanium-smartwatch', 'Forged from aerospace-grade Grade 5 titanium with a sapphire crystal touch display reaching 2,500 nits peak brightness. Features advanced ECG heart tracking, continuous SpO2, skin temperature sensors, dual-band GPS, and 100m water resistance.', 'Aerospace titanium dual-band GPS smartwatch with 14-day battery.', 449, 549, 18, 'Wearables', 'Chronos', '["https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1508685096489-7aacd43bd3b1?auto=format&fit=crop&w=1000&q=80"]', 18, 4.8, 32, 1, 1, '[{"key":"Case Material","value":"Grade 5 Aerospace Titanium"},{"key":"Display","value":"1.43-inch AMOLED (2,500 nits, Sapphire Glass)"},{"key":"Water Resistance","value":"10 ATM (100 Meters)"},{"key":"Battery Life","value":"14 Days Typical Use, 48 Hours GPS Mode"},{"key":"Sensors","value":"Optical Bio-Tracker 5.0, ECG, SpO2, Barometer"}]', '["Offline topological topographic maps with waypoint breadcrumb navigation","Over 160 specialized sports modes including deep scuba and mountaineering","Voice assistant, contactless NFC payment, and Bluetooth calling"]', '["smartwatch","titanium","wearable","fitness","luxury"]', '2026-11-05 08:05:37.923 +00:00', '2026-11-05 08:05:37.923 +00:00');
INSERT INTO `products` (`id`, `name`, `slug`, `description`, `shortDescription`, `price`, `originalPrice`, `discountPercent`, `category`, `brand`, `images`, `stock`, `rating`, `numReviews`, `isFeatured`, `isNewArrival`, `specifications`, `features`, `tags`, `createdAt`, `updatedAt`) VALUES (3, 'Nova Pro 4K Curved OLED Gaming Monitor', 'nova-pro-4k-curved-oled-gaming-monitor', 'A breathtaking 34-inch ultra-wide 1800R curved QD-OLED display with genuine 0.03ms GtG response time and 240Hz refresh rate. True 10-bit color, DisplayHDR True Black 400, and 99.3% DCI-P3 coverage deliver cinema-level contrast and fluid gaming.', '34" Ultrawide QD-OLED 240Hz 0.03ms HDR True Black Gaming Monitor.', 899, 1099, 18, 'Gaming & Setup', 'NovaTech', '["https://images.unsplash.com/photo-1527443224154-c4a3942d3acf?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&w=1000&q=80"]', 9, 4.9, 27, 1, 0, '[{"key":"Panel Type","value":"Quantum Dot OLED (QD-OLED)"},{"key":"Resolution","value":"3440 x 1440 (UWQHD 21:9)"},{"key":"Refresh Rate","value":"240Hz"},{"key":"Response Time","value":"0.03ms (GtG)"},{"key":"Ports","value":"2x DP 1.4, 2x HDMI 2.1, 90W USB-C with KVM"}]', '["Built-in KVM switch to control two PCs with a single keyboard & mouse","G-Sync & FreeSync Premium Pro certified for tear-free gameplay","Custom graphite heatsink prevents OLED burn-in without noisy fans"]', '["monitor","oled","gaming","4k","display"]', '2026-11-05 08:05:37.930 +00:00', '2026-11-05 08:05:37.930 +00:00');
INSERT INTO `products` (`id`, `name`, `slug`, `description`, `shortDescription`, `price`, `originalPrice`, `discountPercent`, `category`, `brand`, `images`, `stock`, `rating`, `numReviews`, `isFeatured`, `isNewArrival`, `specifications`, `features`, `tags`, `createdAt`, `updatedAt`) VALUES (4, 'CyberBlade Wireless Mechanical Keyboard', 'cyberblade-wireless-mechanical-keyboard', 'CNC aluminum unibody 75% hot-swappable mechanical keyboard with gasket mount design, pre-lubed linear switches, sound-dampening IXPE foam, and south-facing per-key RGB backlighting with transparent polycarbonate keycaps.', '75% Gasket Mount Wireless Aluminum Mechanical Keyboard.', 159, 199, 20, 'Gaming & Setup', 'CyberBlade', '["https://images.unsplash.com/photo-1587829741301-dc798b83add3?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1618384887929-16ec33fab9ef?auto=format&fit=crop&w=1000&q=80"]', 45, 4.7, 39, 0, 1, '[{"key":"Layout","value":"75% Compact (81 Keys + Rotary Encoder)"},{"key":"Switches","value":"Factory Lubed Linear Hall-Effect Switches"},{"key":"Mounting","value":"Double Gasket Mount with Poron Dampeners"},{"key":"Connectivity","value":"Tri-Mode: 2.4Ghz Wireless, BT 5.1, USB-C"},{"key":"Battery","value":"4000mAh (Up to 200 Hours RGB off)"}]', '["Solid CNC-milled 6063 aluminum alloy chassis with anodized finish","Programmable tactile multifunction rotary media knob","QMK/VIA open-source custom key remapping and macros support"]', '["keyboard","mechanical","wireless","rgb","gaming"]', '2026-11-05 08:05:37.934 +00:00', '2026-11-05 08:05:37.934 +00:00');
INSERT INTO `products` (`id`, `name`, `slug`, `description`, `shortDescription`, `price`, `originalPrice`, `discountPercent`, `category`, `brand`, `images`, `stock`, `rating`, `numReviews`, `isFeatured`, `isNewArrival`, `specifications`, `features`, `tags`, `createdAt`, `updatedAt`) VALUES (5, 'Aura Flow Cyberpunk Bomber Jacket', 'aura-flow-cyberpunk-bomber-jacket', 'Weatherproof technical nylon outerwear with waterproof YKK AquaGuard zippers, magnetic Fidlock buckle straps, breathable heat-insulating lining, and hidden internal utility pockets. Engineered for all-season metropolitan wear.', 'Waterproof technical streetwear bomber with magnetic utility pockets.', 189, 249, 24, 'Fashion & Apparel', 'Aura Wear', '["https://images.unsplash.com/photo-1551028719-00167b16eac5?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?auto=format&fit=crop&w=1000&q=80"]', 30, 4.8, 19, 1, 1, '[{"key":"Material","value":"Cordura Ripstop 3-Layer Technical Nylon"},{"key":"Waterproof Rating","value":"20,000mm Hydrostatic Head"},{"key":"Hardware","value":"German Fidlock V-Buckles & YKK Matte Zips"},{"key":"Fit","value":"Modern Relaxed Technical Silhouette"}]', '["Detachable sling strap allows carrying jacket over shoulder hands-free","Reflective 3M geometric micro-decals for high visibility night safety","Fleece-lined warming side hand pockets with zippered enclosures"]', '["jacket","streetwear","fashion","techwear","cyberpunk"]', '2026-11-05 08:05:37.940 +00:00', '2026-11-05 08:05:37.940 +00:00');
INSERT INTO `products` (`id`, `name`, `slug`, `description`, `shortDescription`, `price`, `originalPrice`, `discountPercent`, `category`, `brand`, `images`, `stock`, `rating`, `numReviews`, `isFeatured`, `isNewArrival`, `specifications`, `features`, `tags`, `createdAt`, `updatedAt`) VALUES (6, 'Lumina Horizon Ambient Smart Lightbar', 'lumina-horizon-ambient-smart-lightbar', 'Dynamic gradient LED desk and wall ambient lighting fixture with 16 million colors, screen-sync immersion mode, circadian rhythm wake-up sequence, and integration with Apple HomeKit, Google Home, and Alexa.', 'Screen-syncing gradient smart lightbar with music visualizer.', 119, 149, 20, 'Home & Living', 'Lumina', '["https://images.unsplash.com/photo-1507473885765-e6ed057f782c?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1513506003901-1e6a229e2d15?auto=format&fit=crop&w=1000&q=80"]', 40, 4.6, 24, 0, 0, '[{"key":"Luminous Flux","value":"1,200 Lumens (Adjustable 1-100%)"},{"key":"Color Temp","value":"2200K (Warm Sunset) - 6500K (Cool Daylight)"},{"key":"Smart Connectivity","value":"Matter, Thread, Wi-Fi 6, Bluetooth"},{"key":"Power","value":"24W via USB Type-C PD"}]', '["Sub-millisecond HDMI 2.1 video sync for game and movie backlighting","Integrated acoustic sensor for rhythmic musical visualizer beats","Magnetic rotatable base allows 360-degree beam orientation"]', '["lighting","smart-home","rgb","ambiance","setup"]', '2026-11-05 08:05:37.945 +00:00', '2026-11-05 08:05:37.945 +00:00');
INSERT INTO `products` (`id`, `name`, `slug`, `description`, `shortDescription`, `price`, `originalPrice`, `discountPercent`, `category`, `brand`, `images`, `stock`, `rating`, `numReviews`, `isFeatured`, `isNewArrival`, `specifications`, `features`, `tags`, `createdAt`, `updatedAt`) VALUES (7, 'Vortex Precision Wireless Studio Mouse', 'vortex-precision-wireless-studio-mouse', 'Ergonomic sculptured wireless mouse equipped with 30,000 DPI Focus Pro optical sensor, mag-speed dual-mode electromagnetic scrolling wheel, thumb gesture button, and silent optical micro-switches rated for 90 million clicks.', '30,000 DPI silent ergonomic mouse with electromagnetic scroll.', 99, 129, 23, 'Gaming & Setup', 'Vortex Dynamics', '["https://images.unsplash.com/photo-1615663245857-ac93bb7c39e7?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1527864550417-7fd91fc51a46?auto=format&fit=crop&w=1000&q=80"]', 52, 4.7, 41, 0, 0, '[{"key":"Sensor","value":"Focus Pro 30K Optical Sensor"},{"key":"Battery Life","value":"Up to 90 Days on a 2-hour charge"},{"key":"Weight","value":"108g Balanced"},{"key":"Connectivity","value":"2.4Ghz USB Dongle + 3 Bluetooth channels"}]', '["MagSpeed scroll wheel scrolls 1,000 lines in 1 second with hyper-fast mode","Quick-switch button between 3 paired devices seamlessly","USB-C rapid charging: 1 minute of charging gives 3 hours of full use"]', '["mouse","ergonomic","wireless","accessories","setup"]', '2026-11-05 08:05:37.949 +00:00', '2026-11-05 08:05:37.949 +00:00');
INSERT INTO `products` (`id`, `name`, `slug`, `description`, `shortDescription`, `price`, `originalPrice`, `discountPercent`, `category`, `brand`, `images`, `stock`, `rating`, `numReviews`, `isFeatured`, `isNewArrival`, `specifications`, `features`, `tags`, `createdAt`, `updatedAt`) VALUES (8, 'Pulse X Pro True Wireless Earbuds', 'pulse-x-pro-true-wireless-earbuds', 'Compact audiophile earbuds featuring planar magnetic drivers with dynamic subwoofers, active wind-resistant noise canceling, IPX7 water resistance, and wireless charging case delivering 36 hours total playback.', 'Planar magnetic hybrid driver wireless earbuds with IPX7 rating.', 179, 229, 22, 'Audio & Sound', 'Aura Audio', '["https://images.unsplash.com/photo-1590658268037-6bf12165a8df?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1606220588913-b3aacb4d2f46?auto=format&fit=crop&w=1000&q=80"]', 33, 5, 1, 1, 1, '[{"key":"Acoustic Architecture","value":"10mm Planar Magnetic + 6mm Dynamic"},{"key":"Water Resistance","value":"IPX7 (Sweatproof and rainproof)"},{"key":"Battery Life","value":"9 Hours (Earbuds) + 27 Hours (Charging Case)"},{"key":"Audio Codecs","value":"LHDC 5.0, LDAC, AAC, SBC"}]', '["Smart adaptive ANC automatically tunes strength to surrounding decibels","Bone conduction sensor for crystal clear calls in noisy environments","Qi wireless charging and USB-C fast charging support"]', '["earbuds","audio","wireless","anc","ipx7"]', '2026-11-05 08:05:37.955 +00:00', '2026-11-05 08:07:49.494 +00:00');
INSERT INTO `products` (`id`, `name`, `slug`, `description`, `shortDescription`, `price`, `originalPrice`, `discountPercent`, `category`, `brand`, `images`, `stock`, `rating`, `numReviews`, `isFeatured`, `isNewArrival`, `specifications`, `features`, `tags`, `createdAt`, `updatedAt`) VALUES (9, 'Aura Vision Pro AR Smart Glasses', 'aura-vision-pro-ar-smart-glasses', 'Next-generation augmented reality glasses featuring dual 4K micro-OLED displays with 120Hz refresh rates, spatial sound, and full 6-DoF motion tracking. Seamlessly mirror your laptop displays into a private 120-inch floating workspace or immerse in spatial cinema.', 'Dual 4K micro-OLED spatial AR glasses with 6-DoF tracking.', 699, 799, 13, 'Electronics', 'Aura Vision', '["https://images.unsplash.com/photo-1593508512255-86ab42a8e620?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1576086213369-97a306d36557?auto=format&fit=crop&w=1000&q=80"]', 15, 4.9, 38, 1, 1, '[{"key":"Display Technology","value":"Dual 1.3-inch Micro-OLED (3840 x 2160 per eye)"},{"key":"Refresh Rate","value":"120Hz Ultra-Fluid"},{"key":"Field of View","value":"52° FOV (Equivalent to 120-inch screen at 4m)"},{"key":"Weight","value":"142g Ergonomic balanced frame"},{"key":"Connectivity","value":"USB Type-C DisplayPort Alt Mode & Wi-Fi 6E"}]', '["Ultra-high pixel density of 3,552 PPI for razor-sharp text readability","Built-in prescription lens magnetic attachment system","Spatial acoustic speakers directed to ear with zero audio leakage"]', '["electronics","ar","smart-glasses","vr","displays"]', '2026-11-05 08:27:10.411 +00:00', '2026-11-05 08:27:10.411 +00:00');
INSERT INTO `products` (`id`, `name`, `slug`, `description`, `shortDescription`, `price`, `originalPrice`, `discountPercent`, `category`, `brand`, `images`, `stock`, `rating`, `numReviews`, `isFeatured`, `isNewArrival`, `specifications`, `features`, `tags`, `createdAt`, `updatedAt`) VALUES (10, 'QuantumBook Ultra M3 Carbon Laptop', 'quantumbook-ultra-m3-carbon-laptop', 'Crafted from aerospace magnesium-carbon fiber alloy weighing just 1.1kg. Houses a 14.5-inch 3.2K 120Hz OLED display, 12-core AI neural processing engine, 32GB high-speed unified RAM, and up to 22 hours of battery endurance on a single charge.', '14.5" 3.2K 120Hz OLED ultrabook with 22-hour battery life.', 1499, 1699, 12, 'Electronics', 'Quantum Systems', '["https://images.unsplash.com/photo-1517336714731-489689fd1ca8?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1496181133206-80ce9b88a853?auto=format&fit=crop&w=1000&q=80"]', 12, 5, 29, 1, 1, '[{"key":"Processor","value":"12-Core Quantum AI Processor (Up to 4.8 GHz)"},{"key":"RAM & Storage","value":"32GB LPDDR5X + 1TB PCIe 4.0 NVMe SSD"},{"key":"Display","value":"14.5\" 3.2K OLED 120Hz (100% DCI-P3, 500 nits)"},{"key":"Battery","value":"75Wh (Up to 22 Hours Web/Video playback)"},{"key":"Chassis","value":"Forged Magnesium-Carbon Unibody (1.1kg)"}]', '["Zero-fan vapor chamber cooling for silent full-throttle compute","Thunderbolt 4, HDMI 2.1, SD Express card reader, and Wi-Fi 7","1080p FHD IR webcam with hardware privacy shutter"]', '["laptop","ultrabook","electronics","workstation","oled"]', '2026-11-05 08:27:10.427 +00:00', '2026-11-05 08:27:10.427 +00:00');
INSERT INTO `products` (`id`, `name`, `slug`, `description`, `shortDescription`, `price`, `originalPrice`, `discountPercent`, `category`, `brand`, `images`, `stock`, `rating`, `numReviews`, `isFeatured`, `isNewArrival`, `specifications`, `features`, `tags`, `createdAt`, `updatedAt`) VALUES (11, 'Aura Holographic Studio 3D Display', 'aura-holographic-studio-3d-display', 'Breakthrough 16-inch glasses-free spatial holographic 3D monitor. Features high-speed eye-tracking stereo cameras and an optical lenticular lens array that projects dynamic light fields directly into your eyes, creating realistic tangible 3D depth.', '16" Glasses-Free 4K Spatial Lightfield 3D Display.', 1199, 1399, 14, 'Electronics', 'Aura Vision', '["https://images.unsplash.com/photo-1550745165-9bc0b252726f?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1526738549149-8e07eca6c147?auto=format&fit=crop&w=1000&q=80"]', 8, 4.8, 17, 0, 1, '[{"key":"Display Size","value":"15.6 inches Glasses-Free 3D"},{"key":"Panel Resolution","value":"3840 x 2160 (4K UHD 2D / True 3D Depth)"},{"key":"Tracking Cameras","value":"Dual High-Speed Eye-Tracking IR Sensors"},{"key":"Software Support","value":"Unity, Unreal Engine, Blender, Maya, WebXR"}]', '["View 3D models and animations pop out in physical space without any glasses","Instant switch between high-precision 2D 4K mode and holographic 3D","Integrated touch bar controls for 3D rotation, zoom, and perspective"]', '["electronics","3d","holographic","monitor","display"]', '2026-11-05 08:27:10.434 +00:00', '2026-11-05 08:27:10.434 +00:00');
INSERT INTO `products` (`id`, `name`, `slug`, `description`, `shortDescription`, `price`, `originalPrice`, `discountPercent`, `category`, `brand`, `images`, `stock`, `rating`, `numReviews`, `isFeatured`, `isNewArrival`, `specifications`, `features`, `tags`, `createdAt`, `updatedAt`) VALUES (12, 'VoltCore 140W GaN Fast Charger & Power Hub', 'voltcore-140w-gan-fast-charger-power-hub', 'Compact 140W Gallium Nitride (GaN III) multi-device charging station with real-time digital LCD power monitor. Features 3x USB-C PD 3.1 ports and 1x USB-A port capable of charging a 16-inch MacBook Pro, iPad, and smartphone at full speed simultaneously.', '140W GaN III 4-Port desktop fast charger with real-time wattage LCD.', 79, 99, 20, 'Electronics', 'VoltCore', '["https://images.unsplash.com/photo-1583863788434-e58a36330cf0?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1622445262464-84b14e3295b6?auto=format&fit=crop&w=1000&q=80"]', 50, 4.9, 64, 0, 0, '[{"key":"Total Output Power","value":"140W Max (PD 3.1 Supported)"},{"key":"Ports","value":"3x USB Type-C, 1x USB-A"},{"key":"Technology","value":"GaN III (Gallium Nitride Semiconductor)"},{"key":"Display","value":"Real-time Wattage & Protocol Smart LCD Screen"}]', '["Fast charges 16-inch laptop to 50% in just 28 minutes","ActiveShield 2.0 temperature monitoring takes 3 million temperature checks/day","Compact foldable desktop footprint 40% smaller than standard bricks"]', '["electronics","charger","gan","power","accessories"]', '2026-11-05 08:27:10.442 +00:00', '2026-11-05 08:27:10.442 +00:00');
INSERT INTO `products` (`id`, `name`, `slug`, `description`, `shortDescription`, `price`, `originalPrice`, `discountPercent`, `category`, `brand`, `images`, `stock`, `rating`, `numReviews`, `isFeatured`, `isNewArrival`, `specifications`, `features`, `tags`, `createdAt`, `updatedAt`) VALUES (13, 'Aura Drone Air 4K Cine Gimbal Drone', 'aura-drone-air-4k-cine-gimbal-drone', 'Sub-249g ultra-compact folding aerial drone equipped with a 1/1.3-inch 48MP CMOS sensor, 4K/60fps HDR video recording, 3-axis mechanical stabilization gimbal, omnidirectional obstacle avoidance, and up to 45 minutes of extended flight time.', 'Sub-249g 4K/60fps Cine Drone with 45-min flight time.', 749, 899, 17, 'Electronics', 'Aura Vision', '["https://images.unsplash.com/photo-1527977966376-1c8408f9f108?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1507582020474-9a35b7d455d9?auto=format&fit=crop&w=1000&q=80"]', 14, 4.9, 42, 1, 1, '[{"key":"Takeoff Weight","value":"246g (No FAA / Regulatory Registration Needed)"},{"key":"Camera Sensor","value":"1/1.3\" CMOS 48MP (f/1.7 aperture)"},{"key":"Max Flight Time","value":"45 Minutes"},{"key":"Video Transmission","value":"15km Full HD 1080p/60fps live feed"},{"key":"Wind Resistance","value":"Level 5 (Up to 38 km/h)"}]', '["True Vertical Shooting mode for direct high-res social media sharing","ActiveTrack 5.0 and Spotlight subject lock for autonomous cinematic shots","Four-way obstacle sensing system with automated return-to-home"]', '["electronics","drone","camera","4k","aerial"]', '2026-11-05 08:27:10.450 +00:00', '2026-11-05 08:27:10.450 +00:00');
INSERT INTO `products` (`id`, `name`, `slug`, `description`, `shortDescription`, `price`, `originalPrice`, `discountPercent`, `category`, `brand`, `images`, `stock`, `rating`, `numReviews`, `isFeatured`, `isNewArrival`, `specifications`, `features`, `tags`, `createdAt`, `updatedAt`) VALUES (14, 'Nexus Smart AI Security Hub & 4K Wireless Cam', 'nexus-smart-ai-security-hub-4k-wireless-cam', 'Solar-powered wire-free 4K security camera system with built-in bionic AI that recognizes family members, vehicles, and package deliveries locally on-device with zero subscription fees. Features color night vision, 105dB siren, and 365 days of battery reserve.', 'Wire-free 4K HDR Solar AI Camera with zero subscription.', 229, 279, 18, 'Electronics', 'Nexus Living', '["https://images.unsplash.com/photo-1558002038-1055907df827?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1585771724684-38269d6639fd?auto=format&fit=crop&w=1000&q=80"]', 26, 4.7, 31, 0, 1, '[{"key":"Video Quality","value":"4K Ultra HD (3840 x 2160) with HDR"},{"key":"Power System","value":"Integrated Solar Panel + 13,000mAh Battery"},{"key":"Local Storage","value":"32GB eMMC (Expandable up to 2TB SSD on Hub)"},{"key":"Night Vision","value":"Full Color Spotlight Night Vision (Up to 15m)"}]', '["Self-sustaining solar power: 2 hours of direct daily sunlight keeps it charged forever","On-device AI distinguishes humans, pets, vehicles, and deliveries with 99% accuracy","Two-way clear audio with acoustic noise cancellation and 105dB security siren"]', '["electronics","smart-home","security","camera","ai"]', '2026-11-05 08:27:10.458 +00:00', '2026-11-05 08:27:10.458 +00:00');

