INSERT INTO `reviews` (`id`, `userId`, `userName`, `userAvatar`, `productId`, `rating`, `comment`, `verifiedPurchase`, `createdAt`, `updatedAt`) VALUES (2, 2, 'Sophia Martinez', '', 2, 5, 'Stunning titanium finish and the screen is crystal clear even in harsh direct sunlight. ECG and sleep analytics match my medical-grade ring.', 1, '2026-11-05 08:05:37.965 +00:00', '2026-11-05 08:05:37.965 +00:00');
INSERT INTO `reviews` (`id`, `userId`, `userName`, `userAvatar`, `productId`, `rating`, `comment`, `verifiedPurchase`, `createdAt`, `updatedAt`) VALUES (3, 2, 'David Chen', '', 3, 4, 'Great build quality on the CyberBlade keyboard. Gasket mount gives a very pleasing deep thock acoustic sound. Fast delivery too!', 1, '2026-11-05 08:05:37.970 +00:00', '2026-11-05 08:05:37.970 +00:00');
